let transactions=[],selectedMonth="",usingFallback=false;
const $=id=>document.getElementById(id);
window.addEventListener("DOMContentLoaded",()=>{
  document.querySelectorAll(".nav-item").forEach(b=>b.addEventListener("click",()=>showPage(b.dataset.page)));
  document.querySelectorAll("[data-go]").forEach(b=>b.addEventListener("click",()=>showPage(b.dataset.go)));
  $("refreshButton").addEventListener("click",loadData);
  $("monthSelect").addEventListener("change",e=>{selectedMonth=e.target.value;renderAll();});
  $("transactionSearch").addEventListener("input",renderAllTransactions);
  window.addEventListener("resize",debounce(renderVisibleCharts,120));
  loadData();
});
function showPage(page){document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.page===page));document.querySelectorAll(".page").forEach(s=>s.classList.remove("active"));$(`${page}Page`).classList.add("active");$("pageTitle").textContent=page[0].toUpperCase()+page.slice(1);setTimeout(renderVisibleCharts,20)}
async function loadData(){
  setDataStatus("Loading data…","");hideMessage();
  const urls=[
    `https://docs.google.com/spreadsheets/d/${CONFIG.sheetId}/gviz/tq?tqx=out:csv&gid=${CONFIG.gid}&_=${Date.now()}`,
    `https://docs.google.com/spreadsheets/d/${CONFIG.sheetId}/export?format=csv&gid=${CONFIG.gid}&_=${Date.now()}`
  ];
  let parsed=[];let lastError=null;
  for(const url of urls){try{const r=await fetch(url,{cache:"no-store"});if(!r.ok)throw new Error(`HTTP ${r.status}`);const text=await r.text();if(/^\s*</.test(text))throw new Error("Google returned an HTML page instead of CSV");parsed=parseTransactions(parseCSV(text));if(parsed.length)break;throw new Error("No valid rows found");}catch(e){lastError=e;console.warn("Sheet endpoint failed",e);}}
  if(parsed.length){transactions=parsed;usingFallback=false;setDataStatus("Live Google Sheets","live");}
  else{transactions=normalizeRows(FALLBACK_RAW);usingFallback=true;setDataStatus("Snapshot data","fallback");showMessage("Live Google Sheets could not be reached, so the dashboard is showing the uploaded CSV snapshot. Your layout and charts still work. Check Sheet sharing/publishing if you want automatic updates.");console.error(lastError);}
  populateMonthFilter();renderAll();
}
function parseCSV(text){
  const rows=[]; let row=[],cell="",quoted=false;
  for(let i=0;i<text.length;i++){
    const c=text[i];
    if(quoted){
      if(c==='"'&&text[i+1]==='"'){cell+='"';i++;}
      else if(c==='"') quoted=false;
      else cell+=c;
    }else{
      if(c==='"') quoted=true;
      else if(c===','){row.push(cell);cell="";}
      else if(c==='\n'){row.push(cell.replace(/\r$/, ""));rows.push(row);row=[];cell="";}
      else cell+=c;
    }
  }
  if(cell.length||row.length){row.push(cell.replace(/\r$/, ""));rows.push(row)}
  return rows;
}
function parseTransactions(rows){const hi=rows.findIndex(r=>r.some(c=>String(c).trim().toLowerCase()==="month")&&r.some(c=>String(c).trim().toLowerCase()==="amount"));if(hi<0)return[];const headers=rows[hi].map(v=>String(v).trim().toLowerCase());const raw=rows.slice(hi+1).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??""])));return normalizeRows(raw)}
function normalizeRows(rawRows){return rawRows.map(r=>{const amount=toNumber(r.amount);const date=parseDate(r.actual||r.date);return{month:normalizeMonth(r.month,date),date:parseDate(r.date)||date,type:canonicalType(r.type),category:canonicalCategory(r.category),item:String(r.items||r.item||"").trim(),amount,description:String(r.description||"").trim()}}).filter(r=>r.type&&r.amount>0)}
function canonicalType(v){const s=String(v||"").trim();if(/^income$/i.test(s))return"Income";if(/^expense$/i.test(s))return"Expense";return s}
function canonicalCategory(v){const s=String(v||"").trim();if(!s||s==="0")return"Income";return s}
function toNumber(v){return Number(String(v??"").replace(/[^0-9.-]/g,""))||0}
function parseDate(v){const s=String(v||"").trim();if(!s)return null;let m=s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);if(m){const d=new Date(+m[3],+m[1]-1,+m[2]);return isNaN(d)?null:d}const d=new Date(s);return isNaN(d)?null:d}
function normalizeMonth(code,date){const m=String(code||"").match(/A?(\d{2})(\d{2})/i);if(m)return`20${m[1]}-${m[2]}`;if(date)return`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}`;return"Unknown"}
function populateMonthFilter(){const months=[...new Set(transactions.map(r=>r.month).filter(m=>m!=="Unknown"))].sort();if(!months.length){$("monthSelect").innerHTML="<option>No data</option>";return}if(!selectedMonth||!months.includes(selectedMonth))selectedMonth=months[months.length-1];$("monthSelect").innerHTML=months.slice().reverse().map(m=>`<option value="${m}" ${m===selectedMonth?"selected":""}>${formatMonth(m)}</option>`).join("")}
function selectedRows(){return transactions.filter(r=>r.month===selectedMonth)}
function sum(rows,type){return rows.filter(r=>!type||r.type===type).reduce((a,r)=>a+r.amount,0)}
function renderAll(){renderDashboard();renderAllTransactions();renderSavings();renderVisibleCharts()}
function renderDashboard(){const rows=selectedRows(),income=sum(rows,"Income"),expense=sum(rows,"Expense"),savings=income-expense,left=CONFIG.totalBudget-expense;$("totalIncome").textContent=formatMoney(income);$("totalExpense").textContent=formatMoney(expense);$("netSavings").textContent=formatMoney(savings);$("netSavings").className=savings<0?"negative":"positive";$("savingRate").textContent=income?`${(savings/income*100).toFixed(1)}% saving rate`:"No income recorded";$("budgetLeft").textContent=formatMoney(left);$("budgetLeft").className=left<0?"negative":"positive";$("budgetUsage").textContent=`${(expense/CONFIG.totalBudget*100).toFixed(1)}% of budget used`;$("incomeMeta").textContent=formatMonth(selectedMonth);$("expenseMeta").textContent=formatMonth(selectedMonth);renderCategoryBars(rows);renderBudgetTable(rows);renderRecent(rows)}
function monthlySummary(){const map=new Map();for(const r of transactions){if(r.month==="Unknown")continue;if(!map.has(r.month))map.set(r.month,{income:0,expense:0,Albert:0,Annie:0,Other:0});const x=map.get(r.month);if(r.type==="Income"){x.income+=r.amount;const t=`${r.item} ${r.description}`;if(/albert/i.test(t))x.Albert+=r.amount;else if(/annie/i.test(t))x.Annie+=r.amount;else x.Other+=r.amount}else if(r.type==="Expense")x.expense+=r.amount}return[...map.entries()].sort(([a],[b])=>a.localeCompare(b))}
function categoryData(rows){const exp=rows.filter(r=>r.type==="Expense"),total=sum(exp),map=new Map();exp.forEach(r=>map.set(r.category||"Other",(map.get(r.category||"Other")||0)+r.amount));return[...map.entries()].map(([category,amount])=>({category,amount,percent:total?amount/total*100:0})).sort((a,b)=>b.amount-a.amount)}
function renderCategoryBars(rows){const d=categoryData(rows);$("categoryTotal").textContent=formatMoney(d.reduce((a,x)=>a+x.amount,0));$("categoryBars").innerHTML=d.length?d.map((x,i)=>`<div class="category-row"><span class="category-name">${esc(x.category)}</span><div class="category-track"><div class="category-fill" style="width:${Math.max(x.percent,1)}%;background:${CONFIG.palette[i%CONFIG.palette.length]}"></div></div><span class="category-percent">${x.percent.toFixed(1)}%</span><span class="category-amount">${formatMoney(x.amount)}</span></div>`).join(""):`<div class="empty-state">No expenses recorded for this month.</div>`}
function budgetFor(cat){if(CONFIG.categoryBudgets[cat]!=null)return CONFIG.categoryBudgets[cat];return null}
function renderBudgetTable(rows){const d=categoryData(rows);$("budgetTableBody").innerHTML=d.length?d.map(x=>{const b=budgetFor(x.category),left=b==null?null:b-x.amount;return`<tr><td>${esc(x.category)}</td><td class="num">${b==null?"—":formatMoney(b)}</td><td class="num"><strong>${formatMoney(x.amount)}</strong></td><td class="num">${x.percent.toFixed(1)}%</td><td class="num ${left!=null&&left<0?"negative":""}">${left==null?"—":formatMoney(left)}</td></tr>`}).join(""):`<tr><td colspan="5">No expenses recorded.</td></tr>`}
function renderRecent(rows){const list=rows.slice().sort((a,b)=>(b.date?.getTime()||0)-(a.date?.getTime()||0)).slice(0,8);$("recentTableBody").innerHTML=list.map(transactionRow).join("")||`<tr><td colspan="6">No transactions recorded.</td></tr>`}
function transactionRow(r){return`<tr><td>${formatDate(r.date)}</td><td class="type-${r.type.toLowerCase()}">${esc(r.type)}</td><td>${esc(r.item)}</td><td>${esc(r.category)}</td><td class="num"><strong>${formatMoney(r.amount)}</strong></td><td>${esc(r.description)}</td></tr>`}
function renderAllTransactions(){const q=($("transactionSearch")?.value||"").trim().toLowerCase();const list=transactions.filter(r=>!q||`${r.item} ${r.category} ${r.description} ${r.type}`.toLowerCase().includes(q)).sort((a,b)=>(b.date?.getTime()||0)-(a.date?.getTime()||0));$("allTransactionsBody").innerHTML=list.map(r=>`<tr><td>${formatDate(r.date)}</td><td>${formatMonth(r.month)}</td><td class="type-${r.type.toLowerCase()}">${esc(r.type)}</td><td>${esc(r.category)}</td><td>${esc(r.item)}</td><td class="num"><strong>${formatMoney(r.amount)}</strong></td><td>${esc(r.description)}</td></tr>`).join("")}
function renderSavings(){const rows=selectedRows(),income=sum(rows,"Income"),expense=sum(rows,"Expense"),available=income-expense;$("savingIncome").textContent=formatMoney(income);$("savingExpense").textContent=formatMoney(expense);$("savingAvailable").textContent=formatMoney(available);$("savingAvailable").className=available<0?"negative":"positive";$("allocationList").innerHTML=CONFIG.allocations.map(([name,p],i)=>`<div class="allocation-row"><span class="allocation-name"><span style="display:inline-block;width:9px;height:9px;background:${CONFIG.palette[i%CONFIG.palette.length]};margin-right:8px"></span>${name}</span><span class="allocation-percent">${p}%</span><strong class="allocation-value">${formatMoney(Math.max(available,0)*p/100)}</strong></div>`).join("")}
function renderVisibleCharts(){if($("dashboardPage").classList.contains("active")){renderIncomeChart();renderExpenseChart()}if($("savingsPage").classList.contains("active")){renderWaterfall();renderSavingsTrend()}}
function renderIncomeChart(){const s=monthlySummary();barChart($("incomeChart"),s.map(([m])=>formatMonthShort(m)),[{name:"Albert",color:CONFIG.palette[0],data:s.map(([,x])=>x.Albert)},{name:"Annie",color:CONFIG.palette[2],data:s.map(([,x])=>x.Annie)}],true)}
function renderExpenseChart(){const s=monthlySummary();lineChart($("expenseChart"),s.map(([m])=>formatMonthShort(m)),s.map(([,x])=>x.expense),CONFIG.palette[1])}
function renderSavingsTrend(){const s=monthlySummary();lineChart($("savingsTrendChart"),s.map(([m])=>formatMonthShort(m)),s.map(([,x])=>x.income-x.expense),CONFIG.palette[0])}
function renderWaterfall(){const rows=selectedRows(),income=sum(rows,"Income"),expense=sum(rows,"Expense"),saving=income-expense;waterfallChart($("waterfallChart"),[{label:"Income",value:income,color:CONFIG.palette[0]},{label:"Expense",value:-expense,color:CONFIG.palette[1]},{label:"Net Savings",value:saving,color:CONFIG.palette[2],total:true}])}
function svgEl(tag,attrs={}){const e=document.createElementNS("http://www.w3.org/2000/svg",tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);return e}
function setupSVG(el){el.innerHTML="";if(!el.clientWidth||!el.clientHeight)return null;const svg=svgEl("svg",{viewBox:`0 0 ${el.clientWidth} ${el.clientHeight}`,class:"svg-chart",preserveAspectRatio:"none"});el.appendChild(svg);return{svg,w:el.clientWidth,h:el.clientHeight}}
function barChart(el,labels,series,stacked){const s=setupSVG(el);if(!s)return;if(!labels.length)return empty(el);const{svg,w,h}=s,L=46,R=12,T=34,B=40,pw=w-L-R,ph=h-T-B;const totals=labels.map((_,i)=>series.reduce((a,x)=>a+x.data[i],0)),max=Math.max(...totals,1)*1.12;for(let k=0;k<=4;k++){const y=T+ph*k/4;svg.appendChild(svgEl("line",{x1:L,y1:y,x2:w-R,y2:y,class:"grid-line"}));addText(svg,axisMoney(max*(1-k/4)),L-8,y+4,"axis-text","end")}const groupW=pw/labels.length,barW=Math.min(38,groupW*.58);labels.forEach((lab,i)=>{let base=0;series.forEach((ser)=>{const v=ser.data[i]||0,hh=v/max*ph,y=T+ph-(base+v)/max*ph;const rect=svgEl("rect",{x:L+i*groupW+(groupW-barW)/2,y,width:barW,height:Math.max(hh,0),fill:ser.color});rect.addEventListener("mousemove",e=>showTip(e,`${ser.name}: ${formatMoney(v)}`));rect.addEventListener("mouseleave",hideTip);svg.appendChild(rect);base+=v});addText(svg,lab,L+i*groupW+groupW/2,h-14,"axis-text","middle")});let lx=L;series.forEach(ser=>{svg.appendChild(svgEl("rect",{x:lx,y:8,width:10,height:10,fill:ser.color}));addText(svg,ser.name,lx+15,17,"legend-text","start");lx+=80})}
function lineChart(el,labels,data,color){const s=setupSVG(el);if(!s)return;if(!labels.length)return empty(el);const{svg,w,h}=s,L=46,R=15,T=24,B=40,pw=w-L-R,ph=h-T-B,max=Math.max(...data,1)*1.15;for(let k=0;k<=4;k++){const y=T+ph*k/4;svg.appendChild(svgEl("line",{x1:L,y1:y,x2:w-R,y2:y,class:"grid-line"}));addText(svg,axisMoney(max*(1-k/4)),L-8,y+4,"axis-text","end")}const pts=data.map((v,i)=>[L+(labels.length===1?pw/2:i*pw/(labels.length-1)),T+ph-v/max*ph]);svg.appendChild(svgEl("polyline",{points:pts.map(p=>p.join(",")).join(" "),fill:"none",stroke:color,"stroke-width":2}));pts.forEach((p,i)=>{const c=svgEl("circle",{cx:p[0],cy:p[1],r:4,fill:color});c.addEventListener("mousemove",e=>showTip(e,`${labels[i]}: ${formatMoney(data[i])}`));c.addEventListener("mouseleave",hideTip);svg.appendChild(c);addText(svg,labels[i],p[0],h-14,"axis-text","middle")})}
function waterfallChart(el,steps){const s=setupSVG(el);if(!s)return;const{svg,w,h}=s,L=45,R=15,T=26,B=46,pw=w-L-R,ph=h-T-B;let running=0;const states=[];for(const st of steps){if(st.total)states.push({...st,start:0,end:st.value});else{const start=running;running+=st.value;states.push({...st,start,end:running})}}const max=Math.max(...states.flatMap(x=>[x.start,x.end]),1),min=Math.min(...states.flatMap(x=>[x.start,x.end]),0),range=(max-min)||1;for(let k=0;k<=4;k++){const val=max-range*k/4,y=T+(max-val)/range*ph;svg.appendChild(svgEl("line",{x1:L,y1:y,x2:w-R,y2:y,class:"grid-line"}));addText(svg,axisMoney(val),L-8,y+4,"axis-text","end")}const gw=pw/states.length,bw=Math.min(70,gw*.55);states.forEach((st,i)=>{const y1=T+(max-Math.max(st.start,st.end))/range*ph,y2=T+(max-Math.min(st.start,st.end))/range*ph;const rect=svgEl("rect",{x:L+i*gw+(gw-bw)/2,y:y1,width:bw,height:Math.max(y2-y1,2),fill:st.color});rect.addEventListener("mousemove",e=>showTip(e,`${st.label}: ${formatMoney(st.value)}`));rect.addEventListener("mouseleave",hideTip);svg.appendChild(rect);addText(svg,st.label,L+i*gw+gw/2,h-16,"axis-text","middle")})}
function addText(svg,text,x,y,cls,anchor){const t=svgEl("text",{x,y,class:cls,"text-anchor":anchor});t.textContent=text;svg.appendChild(t)}
let tip=null;function showTip(e,text){if(!tip){tip=document.createElement("div");tip.className="tooltip";document.body.appendChild(tip)}tip.textContent=text;tip.style.display="block";tip.style.left=`${e.clientX+12}px`;tip.style.top=`${e.clientY+12}px`}function hideTip(){if(tip)tip.style.display="none"}
function empty(el){el.innerHTML=`<div class="empty-state">No data for this period.</div>`}
function formatMoney(n){const sign=n<0?"-":"",v=Math.abs(n);if(v>=1e9)return sign+(v/1e9).toFixed(v%1e9?1:0)+"B";if(v>=1e6)return sign+(v/1e6).toFixed(v%1e6?1:0)+"M";if(v>=1e3)return sign+(v/1e3).toFixed(v%1e3?1:0)+"K";return sign+Math.round(v).toLocaleString("en-US")}
function axisMoney(n){const v=Math.abs(n);return(n<0?"-":"")+(v>=1e6?(v/1e6).toFixed(v>=1e7?0:1)+"M":v>=1e3?(v/1e3).toFixed(0)+"K":Math.round(v))}
function formatMonth(m){if(!/^\d{4}-\d{2}$/.test(m))return m;const[y,mo]=m.split("-").map(Number);return new Date(y,mo-1,1).toLocaleDateString("en-US",{month:"long",year:"numeric"})}
function formatMonthShort(m){if(!/^\d{4}-\d{2}$/.test(m))return m;const[y,mo]=m.split("-").map(Number);return new Date(y,mo-1,1).toLocaleDateString("en-US",{month:"short",year:"2-digit"})}
function formatDate(d){return d?d.toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"}):"—"}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]))}
function setDataStatus(text,cls){$("dataStatus").textContent=text;$("dataStatus").className=`data-status ${cls}`}
function showMessage(t){$("statusMessage").textContent=t;$("statusMessage").hidden=false}function hideMessage(){$("statusMessage").hidden=true}
function debounce(fn,ms){let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms)}}
